python3 -c 'import math; sm = lambda x: [math.exp(v - max(x)) / sum(math.exp(w - max(x)) for w in x) for v in x]; a = sm([1, 2, 3]); b = sm([1001, 1002, 1003]); exec("def o(x):
 try:
  math.exp(x)
  return False
 except OverflowError:
  return True"); print(round(sum(a), 6), all(abs(p - q) < 1e-12 for p, q in zip(a, b)), o(1001))'
